{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest structural analogue (Morgan similarity 0.4079), has an absolute oral bioavailability of 80% in healthy subjects after a 25 mg tablet compared with intravenous dosing. It shares the methoxyquinoline and vinyl-piperidine core with the query, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tegaserod, a methoxy-substituted indole with a basic center, has only 11% oral bioavailability in patients, attributed to extensive first-pass metabolism and/or efflux. However, its structural similarity to the query is low (Morgan similarity 0.2093), so this provides only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental analogue, viqualine, shows high absolute oral bioavailability (73–80%) in humans and shares the key methoxyquinoline and vinyl-amine features of the query. The structural differences (constrained bicyclic amine and hydroxyl substituent) introduce uncertainty, but the direct human data from the closest analogue outweigh low-similarity low-bioavailability examples such as tegaserod. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The closest analogue, viqualine, differs by ring closure and a hydroxyl substituent, which could alter metabolism, permeability, or efflux.",
    "Human absolute bioavailability data for viqualine come from small studies (n=5).",
    "No specific data on first-pass metabolism or transporter-mediated efflux for the query's constrained bicyclic amine are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

